window.VML_DONNEES_EMBARQUEES = {"enigmes":{"_commentaire":"Généré par outils/immersif/migrer-jeu.py depuis « matieres-premieres ». À compléter : voir MIGRATION-RAPPORT.md.","version":1,"niveaux":[{"id":"matelot","nom":"Essentiel","icone":"🌱","equivalent":"CAP 1","profil":"les notions clés du chapitre, avec des repères"},{"id":"timonier","nom":"Expert","icone":"🔥","equivalent":"CAP 1 approfondi","profil":"sans repères, usages précis, calculs de recettes"}],"escales":[{"numero":1,"id":"la-carriere-pourquoi-preparer-analyser-le-terrain-extraire","titre":"La carrière","lieu":"La carrière d'argile, à ciel ouvert","matiere":"","periode_conseillee":"","episode":"Des gradins d'argile brune, une excavatrice à l'arrêt et un tas fraîchement extrait. Sur un panneau, une grille de carrés numérotés.","scenarimage":"","mot":"ANALYSER","mot_origine":"Le mot-clé de la salle 1.","air":null,"cinematique_ouverture":"transition-e1","cinematique_fin":"fin-e1","etats_decor":[],"enigmes":[{"id":"e1-1","escale":1,"ordre":1,"titre":"Les mots du chantier","decor":"carriere","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"odile","probleme_narratif":"Le panneau de chantier a perdu les définitions de six mots du métier.","enjeu":"Sans le vocabulaire, personne ne comprend le bon de lancement.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, encadré « Mots à connaître »","competence_programme":"Expliquer pourquoi on prépare les matières premières","pourquoi_ce_savoir_ici":"On ne prépare pas une matière dont on ne connaît pas les mots.","reaction_du_decor":{"effet":"eclat","description":"Les définitions se rétablissent une à une sur le panneau."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"gisement-extraction","type":"association","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Un gisement est l'endroit où une matière s'est accumulée naturellement. Une impureté est une matière qu'on ne veut pas dans la pâte (racines, cailloux, fer). Broyer, c'est réduire en petits morceaux ou en poudre. Tamiser, c'est trier les grains selon leur taille avec une grille. Un dégraissant rend la pâte moins collante ; un fondant l'aide à fondre à la cuisson.","_brouillon":["zones"],"matelot":{"paires":[{"g":"Gisement","d":"Endroit où une matière s'est accumulée naturellement"},{"g":"Impureté","d":"Matière qu'on ne veut pas dans la pâte"},{"g":"Broyer","d":"Réduire en petits morceaux ou en poudre"},{"g":"Tamiser","d":"Trier les grains selon leur taille avec une grille"}],"consigne":"Relie chaque mot à sa définition : clique sur un mot, puis sur la bonne définition.","indices":["Les définitions sont dans l'encadré « Mots à connaître ».","Un tamis est une grille.","Une impureté est un intrus dans la pâte."],"dialogue":"Bienvenue à la carrière. Maëlle m'a prévenue : sans le bon de lancement signé, le lot de pâte de demain ne peut pas partir. Je tamponne la première étape : l'extraction. Avant de vous donner mon tampon, je veux être sûre que vous savez pourquoi on prépare les matières, et comment on trouve la bonne argile."},"timonier":{"paires":[{"g":"Gisement","d":"Endroit où une matière s'est accumulée naturellement"},{"g":"Impureté","d":"Racines, cailloux, fer : ce qu'on ne veut pas dans la pâte"},{"g":"Tamiser","d":"Trier les grains selon leur taille avec un tamis"},{"g":"Plastique","d":"Se modèle facilement sans se casser"},{"g":"Dégraissant","d":"Matière ajoutée pour rendre la pâte moins collante"},{"g":"Fondant","d":"Matière qui aide la pâte à fondre à la cuisson"}],"consigne":"Six mots du métier ont perdu leur définition. Reconstitue les six paires.","indices":["Commence par les mots que tu connais déjà.","Dégraissant et fondant ont chacun un effet différent.","Le feldspath est un fondant."],"dialogue":"Bienvenue à la carrière. Maëlle m'a prévenue : sans le bon de lancement signé, le lot de pâte de demain ne peut pas partir. Je tamponne la première étape : l'extraction. Avant de vous donner mon tampon, je veux être sûre que vous savez pourquoi on prépare les matières, et comment on trouve la bonne argile."}},{"id":"e1-2","escale":1,"ordre":2,"titre":"Les panneaux de la filière","decor":"carriere","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"odile","probleme_narratif":"Le vent a mélangé les panneaux de la filière de l'argile.","enjeu":"Une étape oubliée, et l'argile arrive mal préparée à l'atelier.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie I, « Vue d'ensemble »","competence_programme":"Expliquer pourquoi on prépare les matières premières","pourquoi_ce_savoir_ici":"La carrière est le début de la filière : il faut en connaître l'ordre.","reaction_du_decor":{"effet":"ouverture","description":"Les panneaux s'alignent dans le bon sens, de la carrière à la matière prête."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"gisement-extraction","type":"ordre","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Analyse du terrain, extraction, pourrissement, broyage, épuration, maturation : c'est l'ordre du cours, de la carrière à la matière prête à l'emploi.","_brouillon":["zones"],"matelot":{"items":[{"txt":"Analyser le terrain","sous":"échantillons en grille","rang":1},{"txt":"Extraire","sous":"carrière à ciel ouvert","rang":2},{"txt":"Pourrissement","sous":"l'argile reste dehors","rang":3},{"txt":"Broyer","sous":"on casse l'argile","rang":4},{"txt":"Épurer","sous":"tamis et aimants","rang":5},{"txt":"Maturation","sous":"au silo","rang":6}],"consigne":"Les six panneaux de la filière de l'argile ont été mélangés. Remets les étapes dans l'ordre, de la carrière à la matière prête. Utilise les flèches, puis vérifie.","indices":["La première étape se fait avant de creuser.","L'argile reste dehors plusieurs mois avant d'être cassée.","La dernière étape se passe dans un silo."],"dialogue":"Remettez les étapes dans l'ordre, de la carrière à la matière prête."},"timonier":{"items":[{"txt":"Analyser le terrain","rang":1},{"txt":"Extraire","rang":2},{"txt":"Pourrissement","rang":3},{"txt":"Broyer","rang":4},{"txt":"Épurer","rang":5},{"txt":"Maturation","rang":6}],"consigne":"Remets dans l'ordre les six étapes de préparation de l'argile, sans l'aide des repères.","indices":["On analyse le terrain avant d'extraire.","Le pourrissement a lieu avant le broyage.","L'épuration précède la maturation."],"dialogue":"Six étapes, aucun repère : de la carrière à la matière prête."}},{"id":"e1-3","escale":1,"ordre":3,"titre":"Le carnet d'Odile","decor":"carriere","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"odile","probleme_narratif":"Odile a noté des phrases dans son carnet, mais certaines sont fausses.","enjeu":"Une fausse règle dans le carnet, et l'extraction se fait au mauvais moment.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties I et II.1","competence_programme":"Expliquer pourquoi on prépare les matières premières","pourquoi_ce_savoir_ici":"Le carnet d'Odile guide l'équipe d'extraction.","reaction_du_decor":{"effet":"calme","description":"Une coche verte s'affiche à côté de chaque phrase vérifiée."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"gisement-extraction","type":"vraifaux","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Dans la nature, les matières premières ne sont pas prêtes à l'emploi : on les prépare pour obtenir une pâte stable et de qualité constante. Avant d'extraire, on analyse le terrain en prélevant un échantillon par carré d'une grille. L'argile est extraite dans des carrières à ciel ouvert, en général à l'entrée de l'hiver. L'argile grasse, quasiment pure, donne un produit de meilleure qualité que l'argile maigre.","_brouillon":["zones"],"matelot":{"affirmations":[{"txt":"Dans la nature, les matières premières sont prêtes à l'emploi.","vrai":false,"explication":"Elles contiennent des impuretés, des morceaux trop gros, trop d'eau."},{"txt":"Avant d'extraire l'argile, on analyse le terrain.","vrai":true,"explication":"On prélève des échantillons pour repérer la meilleure couche."},{"txt":"L'argile est extraite dans une carrière à ciel ouvert.","vrai":true,"explication":"Avec des excavatrices et des camions-bennes."},{"txt":"On prélève un seul échantillon pour tout le gisement.","vrai":false,"explication":"On en prélève un par carré de la grille."}],"consigne":"Odile, la cheffe de carrière, a noté quatre phrases dans son carnet. Pour chacune, dis si elle est vraie ou fausse.","indices":["Relis le début de la partie I.","Un échantillon par carré de la grille.","Les excavatrices travaillent à ciel ouvert."],"dialogue":"Mon carnet contient des erreurs. Vrai ou faux ?"},"timonier":{"affirmations":[{"txt":"Préparer les matières premières rend la pâte stable et de qualité constante.","vrai":true,"explication":"La pièce se modèle, sèche et cuit toujours de la même façon."},{"txt":"Toutes les couches d'un gisement sont identiques.","vrai":false,"explication":"Les strates sont toutes différentes."},{"txt":"On découpe le terrain en carrés et on prélève un échantillon par carré.","vrai":true,"explication":"On repère ainsi la meilleure couche."},{"txt":"En général, l'extraction a lieu à l'entrée de l'hiver.","vrai":true,"explication":"C'est l'indication du cours."},{"txt":"Une argile « maigre » donne un produit de meilleure qualité qu'une argile « grasse ».","vrai":false,"explication":"L'argile grasse est quasiment pure : c'est elle qui donne le meilleur produit."}],"consigne":"Vérifie les cinq phrases du carnet d'Odile : vraie ou fausse ?","indices":["Un gisement est fait de plusieurs couches.","L'extraction a lieu à l'entrée de l'hiver.","Maigre = sableuse, avec beaucoup d'impuretés."],"dialogue":"Vérifiez mes cinq phrases : je ne recopie que les vraies."}},{"id":"e1-4","escale":1,"ordre":4,"titre":"La fiche d'analyse du terrain","decor":"carriere","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"odile","probleme_narratif":"La fiche d'analyse du terrain est à moitié effacée.","enjeu":"Sans analyse, on ne sait pas si le gisement vaut la peine d'être exploité.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie II.1","competence_programme":"Expliquer pourquoi on prépare les matières premières","pourquoi_ce_savoir_ici":"On analyse le terrain avant d'extraire.","reaction_du_decor":{"effet":"lumiere","description":"La fiche se complète et le tampon d'Odile se pose."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"gisement-extraction","type":"trous","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Avant d'extraire, on analyse le terrain : on le découpe en carrés (une grille) et on prélève un échantillon par carré pour repérer la meilleure couche. L'argile grasse, quasiment pure, donne un produit de meilleure qualité que l'argile maigre, qui contient beaucoup d'impuretés.","_brouillon":["zones"],"niveaux":["timonier"],"timonier":{"texte":"<p>Avant d'extraire l'argile, on [[analyse]] le terrain : on le découpe en carrés, c'est une [[grille]], et on prélève un [[échantillon]] par carré. On repère ainsi la meilleure [[couche]]. Une argile « [[grasse]] » est quasiment pure : le produit est de meilleure qualité. Une argile « [[maigre]] » contient beaucoup d'impuretés.</p>","etiquettes":["analyse","grille","échantillon","couche","grasse","maigre","émail","vitrifiée"],"consigne":"Complète la fiche d'analyse du terrain avec les bonnes étiquettes. Deux étiquettes sont en trop.","indices":["Le premier mot manquant est une action qui précède l'extraction.","On découpe le terrain en carrés : cela dessine une grille.","Les étiquettes en trop parlent de cuisson et de verre."],"dialogue":"La fiche d'analyse a des trous. Deux étiquettes sont des pièges."}}]},{"numero":2,"id":"le-parc-d-argile-et-le-silo-le-pourrissement-et-la-maturation","titre":"Le parc d'argile et le silo","lieu":"Le parc d'argile et le silo, derrière la carrière","matiere":"","periode_conseillee":"","episode":"Un grand tas d'argile sous la pluie, et, à côté, un silo sombre et humide. Un tableau affiche des dates et des pourcentages.","scenarimage":"","mot":"REPOSER","mot_origine":"Le mot-clé de la salle 2.","air":null,"cinematique_ouverture":"transition-e2","cinematique_fin":"fin-e2","etats_decor":[],"enigmes":[{"id":"e2-1","escale":2,"ordre":1,"titre":"Dehors, sous la pluie","decor":"parc","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"malik","probleme_narratif":"Malik hésite : que se passe-t-il quand l'argile reste dehors sous la pluie ?","enjeu":"S'il se trompe, l'argile sera mise au silo trop tôt.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie II.2","competence_programme":"Expliquer le pourrissement de l'argile","pourquoi_ce_savoir_ici":"Le pourrissement est la première phase de repos de l'argile.","reaction_du_decor":{"effet":"calme","description":"La pluie s'arrête et l'argile s'assombrit doucement."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"pourrissement-maturation","type":"vraifaux","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Pendant le pourrissement, l'argile est stockée dehors pendant 3 à 24 mois. La pluie, le gel et le dégel fragmentent les grains, et des bactéries décomposent les restes de plantes. L'argile devient plus plastique et plus résistante.","_brouillon":["zones"],"matelot":{"affirmations":[{"txt":"Pendant le pourrissement, l'argile est stockée dehors.","vrai":true,"explication":"Elle subit la pluie, le gel et le dégel."},{"txt":"Le pourrissement dure quelques jours.","vrai":false,"explication":"Il dure de 3 à 24 mois."},{"txt":"La pluie, le gel et le dégel fragmentent les grains.","vrai":true,"explication":"C'est ce qui rend l'argile plus fine."},{"txt":"Après le pourrissement, l'argile est plus plastique et plus résistante.","vrai":true,"explication":"C'est le résultat de cette étape."}],"consigne":"Malik surveille le parc d'argile. Pour chacune de ses quatre phrases, dis si elle est vraie ou fausse.","indices":["Relis le paragraphe « Le pourrissement ».","L'argile reste dehors.","On compte en mois, pas en jours."],"dialogue":"Voilà mes phrases sur le pourrissement. Vrai ou faux ?"},"timonier":{"affirmations":[{"txt":"Le pourrissement dure de 3 à 24 mois.","vrai":true,"explication":"L'argile est stockée dehors pendant tout ce temps."},{"txt":"Des bactéries décomposent les restes de plantes.","vrai":true,"explication":"Elles nettoient l'argile."},{"txt":"Seule la pluie agit sur l'argile : le gel ne sert à rien.","vrai":false,"explication":"Le gel et le dégel fragmentent aussi les grains."},{"txt":"Après le pourrissement, l'argile est moins plastique.","vrai":false,"explication":"Elle devient plus plastique et plus résistante."},{"txt":"L'argile est stockée à l'abri, dans un hangar fermé.","vrai":false,"explication":"Elle est stockée dehors."}],"consigne":"Malik a noté cinq phrases sur le pourrissement. Vraie ou fausse ?","indices":["La durée se compte en mois.","Gel et dégel fragmentent les grains.","Les bactéries s'attaquent aux restes de plantes."],"dialogue":"Cinq phrases sur le pourrissement. Attention aux durées."}},{"id":"e2-2","escale":2,"ordre":2,"titre":"Le parc ou le silo ?","decor":"parc","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"malik","probleme_narratif":"Les étiquettes du parc et du silo sont mélangées.","enjeu":"Une argile mal rangée mûrit trop vite ou pas du tout.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties II.2 et III.3","competence_programme":"Expliquer le pourrissement de l'argile","pourquoi_ce_savoir_ici":"On distingue ce qui se passe dehors et ce qui se passe au silo.","reaction_du_decor":{"effet":"ouverture","description":"Les étiquettes se collent sur le tas et sur la porte du silo."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"pourrissement-maturation","type":"tri","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Le pourrissement a lieu dehors, de 3 à 24 mois : pluie, gel, dégel et bactéries rendent l'argile plus plastique et plus résistante. La maturation a lieu dans un silo humide et sombre, au moins 2 semaines : l'humidité baisse.","_brouillon":["zones"],"matelot":{"colonnes":[{"id":"pou","titre":"Pourrissement"},{"id":"mat","titre":"Maturation"}],"cartes":[{"txt":"Stockée dehors","col":"pou"},{"txt":"Pluie, gel et dégel","col":"pou"},{"txt":"De 3 à 24 mois","col":"pou"},{"txt":"Silo humide et sombre","col":"mat"},{"txt":"Au moins 2 semaines","col":"mat"},{"txt":"L'humidité baisse","col":"mat"}],"consigne":"Range chaque étiquette : pourrissement (dehors) ou maturation (au silo) ?","indices":["Pourrissement = dehors, sous la pluie.","Maturation = dans un silo, à l'abri.","Le silo est humide et sombre."],"dialogue":"Dehors ou au silo ? Rangez chaque étiquette."},"timonier":{"colonnes":[{"id":"pou","titre":"Pourrissement"},{"id":"mat","titre":"Maturation"}],"cartes":[{"txt":"Stockée dehors","col":"pou"},{"txt":"Les grains se fragmentent","col":"pou"},{"txt":"Des bactéries décomposent les restes de plantes","col":"pou"},{"txt":"De 3 à 24 mois","col":"pou"},{"txt":"Silo humide et sombre","col":"mat"},{"txt":"Au moins 2 semaines","col":"mat"},{"txt":"Le taux d'humidité baisse","col":"mat"},{"txt":"De 18-22 % à 13-18 % d'humidité","col":"mat"}],"consigne":"Range les huit étiquettes : pourrissement ou maturation ? Attention aux durées.","indices":["Les durées ne sont pas les mêmes : mois d'un côté, semaines de l'autre.","L'humidité baisse pendant la maturation.","Les bactéries travaillent dehors."],"dialogue":"Huit étiquettes : pourrissement ou maturation. Les durées comptent."}},{"id":"e2-3","escale":2,"ordre":3,"titre":"Le taux d'humidité","decor":"parc","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"malik","probleme_narratif":"L'hygromètre de Malik affiche des chiffres que personne ne comprend.","enjeu":"Une argile trop humide ou trop sèche se travaille mal.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.3","competence_programme":"Expliquer le pourrissement de l'argile","pourquoi_ce_savoir_ici":"Le taux d'humidité dit si l'argile est prête.","reaction_du_decor":{"effet":"eclat","description":"L'aiguille de l'hygromètre se stabilise."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"pourrissement-maturation","type":"qcm","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"L'argile fraîchement extraite contient de 18 % à 22 % d'eau. Après la maturation (au moins 2 semaines en silo), son taux d'humidité baisse : de 13 % à 18 %.","_brouillon":["zones"],"matelot":{"questions":[{"q":"L'argile fraîchement extraite contient…","options":["de 18 % à 22 % d'eau","de 50 % à 60 % d'eau","moins de 5 % d'eau"],"bonne":0,"explication":"C'est le taux d'humidité de l'argile fraîche."},{"q":"Pendant la maturation, le taux d'humidité…","options":["monte","baisse","ne change pas"],"bonne":1,"explication":"Ses propriétés changent et son taux d'humidité baisse."},{"q":"L'argile reste en silo au moins…","options":["2 jours","2 semaines","2 ans"],"bonne":1,"explication":"Au moins 2 semaines, dans un silo humide et sombre."}],"consigne":"Malik te pose trois questions sur l'humidité de l'argile. Choisis la bonne réponse à chacune.","indices":["Le taux d'humidité, c'est la quantité d'eau.","Il baisse pendant la maturation.","Regarde le tableau de la partie III.3."],"dialogue":"Je vous pose trois questions sur l'humidité."},"timonier":{"questions":[{"q":"Après la maturation, le taux d'humidité est de…","options":["18 % à 22 %","13 % à 18 %","5 % à 8 %"],"bonne":1,"explication":"Il baisse par rapport à l'argile fraîchement extraite."},{"q":"Que devient l'argile après le pourrissement ?","options":["Plus plastique et plus résistante","Plus sableuse","Plus rouge"],"bonne":0,"explication":"Les grains se fragmentent et les restes de plantes sont décomposés."},{"q":"Où se fait la maturation ?","options":["Dehors, sous la pluie","Dans un four","Dans un silo humide et sombre"],"bonne":2,"explication":"L'argile y est entreposée au moins 2 semaines."}],"consigne":"Malik veut vérifier tes chiffres. Réponds à ses trois questions.","indices":["Les deux fourchettes se recoupent un peu.","Fraîche : 18 à 22 %.","Après maturation : 13 à 18 %."],"dialogue":"Trois questions de chiffres : je veux des réponses précises."}},{"id":"e2-4","escale":2,"ordre":4,"titre":"Le cadran du silo","decor":"parc","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"malik","probleme_narratif":"La porte du silo est fermée par un cadran à trois molettes.","enjeu":"Sans ouvrir le silo, on ne peut pas sortir l'argile mûre.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties II.2 et III.3","competence_programme":"Expliquer le pourrissement de l'argile","pourquoi_ce_savoir_ici":"Trois nombres du chapitre ouvrent le cadran.","reaction_du_decor":{"effet":"ouverture","description":"Le cadran s'ouvre avec un déclic."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"pourrissement-maturation","type":"code","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Le pourrissement dure au plus 24 mois. La maturation dure au moins 2 semaines. Après la maturation, le taux d'humidité va jusqu'à 18 % au plus.","_brouillon":["zones"],"niveaux":["timonier"],"timonier":{"champs":[{"libelle":"Durée maximale du pourrissement (mois)","valeur":"24","longueur":2},{"libelle":"Durée minimale de la maturation (semaines)","valeur":"2","longueur":1},{"libelle":"Taux d'humidité maximal après maturation (%)","valeur":"18","longueur":2}],"consigne":"Le cadran du silo a trois molettes. Trouve les trois nombres.","indices":["Le premier nombre est un nombre de mois : le plus grand de la fourchette 3 à 24.","Le deuxième nombre est un nombre de semaines.","Le troisième est un pourcentage : le plus grand de la fourchette 13 à 18."],"dialogue":"Trois molettes : trois nombres du chapitre."}}]},{"numero":3,"id":"l-atelier-de-broyage-les-machines-a-broyer-l-argile","titre":"L'atelier de broyage","lieu":"L'atelier de broyage","matiere":"","periode_conseillee":"","episode":"Des machines alignées le long d'un convoyeur : meule, marteaux, cylindre à billes. Chaque poste a perdu sa plaque.","scenarimage":"","mot":"BROYER","mot_origine":"Le mot-clé de la salle 3.","air":null,"cinematique_ouverture":"transition-e3","cinematique_fin":"fin-e3","etats_decor":[],"enigmes":[{"id":"e3-1","escale":3,"ordre":1,"titre":"Les plaques des machines","decor":"broyage","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"karim","probleme_narratif":"Les plaques des machines sont tombées de leur support.","enjeu":"Karim ne peut pas lancer un broyage sans savoir quelle machine fait quoi.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.1, tableau des machines","competence_programme":"Expliquer ce qu'est le broyage","pourquoi_ce_savoir_ici":"Chaque machine broie à sa façon.","reaction_du_decor":{"effet":"eclat","description":"Chaque plaque retrouve sa machine."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"broyage","type":"association","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Broyeur à meule : deux meules qui tournent écrasent l'argile. Brise-mottes : des rouleaux ou des marteaux cassent les mottes. Désagrégateur : une chemise lisse et une chemise striée avec des lames désagrègent l'argile. Broyeur à marteaux : des marteaux qui tournent vite frappent l'argile. Broyeur à billes : un cylindre rempli de billes qui tourne ; le frottement fragmente l'argile.","_brouillon":["zones"],"matelot":{"paires":[{"g":"Broyeur à meule","d":"Deux meules qui tournent écrasent l'argile"},{"g":"Brise-mottes","d":"Des rouleaux ou des marteaux cassent les mottes"},{"g":"Broyeur à marteaux","d":"Des marteaux qui tournent vite frappent l'argile"},{"g":"Broyeur à billes","d":"Un cylindre qui tourne, rempli de billes"}],"consigne":"Les plaques de quatre machines sont tombées. Relie chaque machine à sa façon de fonctionner.","indices":["Le tableau des machines est dans la partie III.1.","Les meules écrasent.","Les billes frottent."],"dialogue":"Ça grince, ça gronde, ça casse : c'est l'atelier de broyage. Pas de panique, mais tous les postes ont perdu leur plaque ce matin, et je ne sais plus quelle machine fait quoi. Aidez-moi à tout remettre en place : le tampon de l'étape trois est pour vous."},"timonier":{"paires":[{"g":"Broyeur à meule","d":"Deux meules qui tournent écrasent l'argile"},{"g":"Brise-mottes","d":"Des rouleaux ou des marteaux cassent les mottes"},{"g":"Désagrégateur","d":"Une chemise lisse et une chemise striée avec des lames"},{"g":"Broyeur à marteaux","d":"Des marteaux qui tournent vite, sortie par une grille"},{"g":"Broyeur à billes (alsing)","d":"Le frottement des billes dans un cylindre qui tourne"}],"consigne":"Cinq machines de l'atelier ont perdu leur plaque. Relie chaque machine à son principe.","indices":["Chaque machine a un verbe : écraser, casser, désagréger, frapper, frotter.","La chemise striée porte des lames.","Le marteau frappe, le brise-mottes casse."],"dialogue":"Ça grince, ça gronde, ça casse : c'est l'atelier de broyage. Pas de panique, mais tous les postes ont perdu leur plaque ce matin, et je ne sais plus quelle machine fait quoi. Aidez-moi à tout remettre en place : le tampon de l'étape trois est pour vous."}},{"id":"e3-2","escale":3,"ordre":2,"titre":"Le plan de l'atelier","decor":"broyage","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"karim","probleme_narratif":"Le plan de l'atelier n'a plus de noms de machines.","enjeu":"Une machine au mauvais poste, et le broyage s'arrête.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.1","competence_programme":"Expliquer ce qu'est le broyage","pourquoi_ce_savoir_ici":"Chaque machine a sa place dans l'atelier.","reaction_du_decor":{"effet":"ouverture","description":"Les noms s'inscrivent sur le plan, poste par poste."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"broyage","type":"plan","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Poste meule : deux meules écrasent l'argile. Poste marteaux : l'argile sort par une grille quand elle est assez fine. Poste billes : un cylindre qui tourne rempli de billes ; broyage à sec ou avec de l'eau. Poste mottes : des rouleaux ou des marteaux cassent les mottes. Poste lames : une chemise lisse et une chemise striée désagrègent l'argile.","_brouillon":["zones"],"matelot":{"titre":"Le plan de l'atelier de broyage","colonnes":2,"cases":[{"libelle":"Poste 1 : deux meules qui tournent écrasent l'argile","reponse":"Broyeur à meule"},{"libelle":"Poste 2 : des marteaux frappent l'argile, qui sort par une grille","reponse":"Broyeur à marteaux"},{"libelle":"Poste 3 : un cylindre qui tourne, rempli de billes","reponse":"Broyeur à billes"},{"libelle":"Poste 4 : des rouleaux cassent les mottes","reponse":"Brise-mottes"}],"etiquettes":["Broyeur à meule","Broyeur à marteaux","Broyeur à billes","Brise-mottes","Tamis vibrant"],"consigne":"Karim range son atelier. Place chaque machine sur le bon poste : clique sur une étiquette, puis sur la case. Une étiquette est en trop.","indices":["Lis la description écrite sur chaque poste.","Le broyeur à billes contient des billes.","Le brise-mottes casse les mottes."],"dialogue":"Placez chaque machine sur son poste."},"timonier":{"titre":"Le plan de l'atelier de broyage","colonnes":2,"cases":[{"libelle":"Poste 1 : l'argile sort quand elle est assez fine, à travers une grille","reponse":"Broyeur à marteaux"},{"libelle":"Poste 2 : deux meules qui tournent","reponse":"Broyeur à meule"},{"libelle":"Poste 3 : un tiers de billes, un tiers d'argile, un tiers d'eau","reponse":"Broyeur à billes"},{"libelle":"Poste 4 : une chemise lisse et une chemise striée avec des lames","reponse":"Désagrégateur"},{"libelle":"Poste 5 : des rouleaux ou des marteaux qui cassent les mottes","reponse":"Brise-mottes"}],"etiquettes":["Broyeur à marteaux","Broyeur à meule","Broyeur à billes","Désagrégateur","Brise-mottes","Tamis vibrant","Concasseur à mâchoires"],"consigne":"Place chaque machine sur le poste qui correspond à sa description. Deux étiquettes sont en trop.","indices":["Chaque machine a une façon de fonctionner différente.","La grille de sortie est celle du broyeur à marteaux.","Les lames sont dans le désagrégateur."],"dialogue":"Placez chaque machine sur le poste de sa description. Deux étiquettes sont en trop."}},{"id":"e3-3","escale":3,"ordre":3,"titre":"Les questions de Karim","decor":"broyage","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"karim","probleme_narratif":"Karim veut vérifier que vous savez choisir une machine.","enjeu":"Une mauvaise machine, et l'argile sort mal broyée.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.1","competence_programme":"Expliquer ce qu'est le broyage","pourquoi_ce_savoir_ici":"Choisir sa machine, c'est connaître ce qu'elle fait.","reaction_du_decor":{"effet":"lumiere","description":"Les voyants des machines passent au vert."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"broyage","type":"qcm","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Broyer, c'est casser l'argile en petits morceaux : on réduit sa taille. Dans le broyeur à billes, le frottement des billes fragmente l'argile ; le broyage se fait à sec ou avec de l'eau (un tiers de billes, un tiers d'argile, un tiers d'eau). Dans le broyeur à marteaux, l'argile sort à travers une grille quand elle est assez fine.","_brouillon":["zones"],"matelot":{"questions":[{"q":"Broyer l'argile, c'est…","options":["la casser en petits morceaux","la faire cuire","la colorer"],"bonne":0,"explication":"On réduit sa taille."},{"q":"Dans un broyeur à billes, l'argile est fragmentée par…","options":["des lames","le frottement des billes","un aimant"],"bonne":1,"explication":"Le cylindre tourne et les billes frottent l'argile."},{"q":"Dans le broyeur à marteaux, l'argile sort…","options":["quand elle est assez fine, à travers une grille","dès qu'elle est entrée","par le haut, en poussière"],"bonne":0,"explication":"La grille ne laisse passer que l'argile assez fine."}],"consigne":"Karim te pose trois questions sur le broyage. Choisis la bonne réponse à chacune.","indices":["Broyer, c'est réduire la taille.","Les billes frottent contre l'argile.","La grille laisse passer l'argile assez fine."],"dialogue":"Trois questions sur le broyage."},"timonier":{"questions":[{"q":"Broyage à l'eau dans un broyeur à billes : les proportions sont…","options":["un tiers de billes, un tiers d'argile, un tiers d'eau","la moitié d'eau, le reste d'argile","uniquement des billes et de l'eau"],"bonne":0,"explication":"Trois tiers égaux, indique le cours."},{"q":"Le broyeur à billes peut broyer…","options":["seulement à sec","à sec ou avec de l'eau","seulement avec de l'eau"],"bonne":1,"explication":"Les deux sont possibles."},{"q":"Le désagrégateur fonctionne avec…","options":["deux meules","une chemise lisse et une chemise striée avec des lames","un aimant"],"bonne":1,"explication":"Les lames désagrègent l'argile."}],"consigne":"Karim veut être sûr que tu connais les détails. Réponds à ses trois questions.","indices":["Relis le tableau des machines.","Trois tiers égaux.","Le désagrégateur travaille avec des lames."],"dialogue":"Trois questions de détail : je ne confie pas les machines à n'importe qui."}},{"id":"e3-4","escale":3,"ordre":4,"titre":"La machine qui ne broie pas","decor":"broyage","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"karim","probleme_narratif":"Cinq machines tournent, mais une ne broie pas l'argile.","enjeu":"Si l'intruse reste dans la liste, le broyage est faux.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties III.1 et III.2","competence_programme":"Expliquer ce qu'est le broyage","pourquoi_ce_savoir_ici":"Une seule machine de l'atelier ne sert pas à broyer.","reaction_du_decor":{"effet":"calme","description":"La machine intruse s'arrête, les autres continuent."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"broyage","type":"intrus","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Le tamis vibrant n'est pas un broyeur : il trie les grains selon leur taille et élimine les impuretés. Il appartient à l'épuration. Meule, marteaux, désagrégateur et brise-mottes cassent ou écrasent l'argile.","_brouillon":["zones"],"niveaux":["timonier"],"timonier":{"cartes":[{"txt":"Broyeur à meule","sous":"deux meules","intrus":false},{"txt":"Broyeur à marteaux","sous":"grille de sortie","intrus":false},{"txt":"Désagrégateur","sous":"lames","intrus":false},{"txt":"Tamis vibrant","sous":"trie les grains","intrus":true},{"txt":"Brise-mottes","sous":"casse les mottes","intrus":false}],"consigne":"Quatre machines de cet atelier broient l'argile. Une seule ne sert pas à la broyer : trouve l'intrus.","indices":["Cherche la machine qui ne casse rien.","Elle trie.","Elle utilise une grille qui vibre."],"dialogue":"Quatre machines broient l'argile. Laquelle n'est pas à sa place ?"}}]},{"numero":4,"id":"la-station-d-epuration-tamisage-deferrage-flottation-et-securite","titre":"La station d'épuration","lieu":"La station d'épuration","matiere":"","periode_conseillee":"","episode":"Un tamis qui vibre, un tambour à aimants et une cellule pleine de bulles. Au mur, un panneau de sécurité.","scenarimage":"","mot":"ÉPURER","mot_origine":"Le mot-clé de la salle 4.","air":null,"cinematique_ouverture":"transition-e4","cinematique_fin":"fin-e4","etats_decor":[],"enigmes":[{"id":"e4-1","escale":4,"ordre":1,"titre":"Tamis ou aimant ?","decor":"epuration","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jade","probleme_narratif":"Le tamis vibrant et l'aimant se partagent les étiquettes.","enjeu":"Un morceau de fer dans la pâte, et la pièce éclate à la cuisson.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.2","competence_programme":"Dire à quoi servent le tamis vibrant et le séparateur magnétique","pourquoi_ce_savoir_ici":"Tamisage et déferrage n'enlèvent pas la même chose.","reaction_du_decor":{"effet":"ouverture","description":"Les étiquettes se placent sous le tamis ou sous l'aimant."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"epuration-purification","type":"tri","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Le tamis vibrant trie les grains selon leur taille : il élimine les impuretés (feuilles, racines) et les grains trop gros. Le déferrage utilise des aimants ou des électro-aimants qui attirent les particules de fer ; il sépare le fer de l'argile, sèche ou en barbotine.","_brouillon":["zones"],"matelot":{"colonnes":[{"id":"tam","titre":"Tamisage"},{"id":"def","titre":"Déferrage"}],"cartes":[{"txt":"Trie les grains selon leur taille","col":"tam"},{"txt":"Élimine feuilles et racines","col":"tam"},{"txt":"Un tamis vibrant","col":"tam"},{"txt":"Attire les particules de fer","col":"def"},{"txt":"Des aimants","col":"def"},{"txt":"Sépare le fer de l'argile","col":"def"}],"consigne":"Range chaque étiquette : tamisage (tamis vibrant) ou déferrage (aimants) ?","indices":["Le tamis a une grille.","Un aimant attire le fer.","Le tamis garde les racines et les gros grains."],"dialogue":"Tamis ou aimant ? Rangez chaque étiquette."},"timonier":{"colonnes":[{"id":"tam","titre":"Tamisage"},{"id":"def","titre":"Déferrage"}],"cartes":[{"txt":"Trie les grains selon leur taille","col":"tam"},{"txt":"Élimine les impuretés","col":"tam"},{"txt":"Retire les grains trop gros","col":"tam"},{"txt":"Un tamis vibrant","col":"tam"},{"txt":"Aimants ou électro-aimants","col":"def"},{"txt":"Attire les particules de fer","col":"def"},{"txt":"Fonctionne sur l'argile sèche ou en barbotine","col":"def"},{"txt":"Épuration magnétique","col":"def"}],"consigne":"Range les huit étiquettes : tamisage ou déferrage ? Attention aux détails.","indices":["Barbotine = argile avec de l'eau.","Le tamis trie selon la taille.","L'aimant ne retient que le fer."],"dialogue":"Huit étiquettes : tamisage ou déferrage. Attention aux détails."}},{"id":"e4-2","escale":4,"ordre":2,"titre":"La cellule de flottation","decor":"epuration","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jade","probleme_narratif":"Les étapes de la cellule de flottation sont dans le désordre.","enjeu":"Une étape sautée, et les deux poudres restent mélangées.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie IV.4","competence_programme":"Dire à quoi servent le tamis vibrant et le séparateur magnétique","pourquoi_ce_savoir_ici":"La flottation sépare deux poudres de nature différente.","reaction_du_decor":{"effet":"calme","description":"Les bulles remontent, la cellule se met en route."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"epuration-purification","type":"ordre","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Flottation : on met de l'eau et de la poudre dans un même mélange, puis on ajoute des réactifs et de l'air. Une des matières s'accroche aux bulles et monte en mousse ; l'autre reste au fond. Exemple : séparer le feldspath de la silice.","_brouillon":["zones"],"matelot":{"items":[{"txt":"On mélange l'eau et la poudre","sous":"le point de départ","rang":1},{"txt":"On ajoute des réactifs et de l'air","sous":"des bulles apparaissent","rang":2},{"txt":"Une matière s'accroche aux bulles","sous":"elle est attirée","rang":3},{"txt":"Elle monte en mousse, l'autre reste au fond","sous":"les deux sont séparées","rang":4}],"consigne":"Jade te montre la flottation, qui sépare deux poudres. Remets les quatre étapes dans l'ordre.","indices":["On commence par préparer le mélange.","Les réactifs et l'air viennent avant les bulles.","La mousse se forme en dernier."],"dialogue":"Remettez les étapes de la flottation dans l'ordre."},"timonier":{"items":[{"txt":"On mélange l'eau et la poudre","rang":1},{"txt":"On ajoute des réactifs et de l'air","rang":2},{"txt":"Une matière s'accroche aux bulles","rang":3},{"txt":"Elle monte en mousse","rang":4},{"txt":"L'autre matière reste au fond","rang":5}],"consigne":"Remets dans l'ordre les cinq étapes de la flottation, sans l'aide des repères.","indices":["Eau et poudre d'abord.","Réactifs et air ensuite.","Une matière monte, l'autre reste."],"dialogue":"Cinq étapes, sans repères : l'ordre de la flottation."}},{"id":"e4-3","escale":4,"ordre":3,"titre":"Le panneau de sécurité","decor":"epuration","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jade","probleme_narratif":"Le panneau de sécurité de la station est couvert de phrases.","enjeu":"Une mauvaise habitude, et la poussière devient un danger.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, encadré « Sécurité »","competence_programme":"Dire à quoi servent le tamis vibrant et le séparateur magnétique","pourquoi_ce_savoir_ici":"La sécurité passe avant tout à la station d'épuration.","reaction_du_decor":{"effet":"lumiere","description":"Le voyant du panneau passe au vert."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"epuration-purification","type":"vraifaux","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Le broyage, le concassage et le tamisage produisent des poussières fines (silice, argile sèche) dangereuses pour les poumons. Il faut porter un masque, travailler avec aspiration ou à l'humide, et ne jamais balayer à sec.","_brouillon":["zones"],"matelot":{"affirmations":[{"txt":"Le broyage et le tamisage produisent des poussières fines.","vrai":true,"explication":"De la silice, de l'argile sèche."},{"txt":"Ces poussières sont dangereuses pour les poumons.","vrai":true,"explication":"On ne les respire pas."},{"txt":"On peut balayer à sec pour nettoyer.","vrai":false,"explication":"Cela remet la poussière en l'air."},{"txt":"On porte un masque dans la station.","vrai":true,"explication":"C'est une règle de sécurité."}],"consigne":"Jade rappelle les règles de sécurité de la station. Pour chaque phrase, dis si elle est vraie ou fausse.","indices":["Relis l'encadré « Sécurité ».","Les poussières fines se respirent.","Balayer à sec soulève la poussière."],"dialogue":"Rappel des règles de sécurité. Vrai ou faux ?"},"timonier":{"affirmations":[{"txt":"Le broyage, le concassage et le tamisage produisent des poussières fines.","vrai":true,"explication":"Silice et argile sèche."},{"txt":"La poussière d'argile sèche est sans danger pour les poumons.","vrai":false,"explication":"Elle est dangereuse, comme la silice."},{"txt":"Travailler avec aspiration ou à l'humide réduit les poussières.","vrai":true,"explication":"Ce sont les deux moyens du cours."},{"txt":"On peut balayer à sec si on est rapide.","vrai":false,"explication":"On ne balaie jamais à sec."},{"txt":"Le masque est facultatif si on tamise peu de temps.","vrai":false,"explication":"Le masque se porte pour le broyage, le concassage et le tamisage."}],"consigne":"Le panneau de sécurité de la station a cinq phrases. Vraie ou fausse ?","indices":["Le masque protège les poumons.","À l'humide, la poussière ne vole pas.","Balayer à sec la remet en l'air."],"dialogue":"Cinq phrases sur la sécurité : repérez les mauvais gestes."}},{"id":"e4-4","escale":4,"ordre":4,"titre":"La fiche de poste","decor":"epuration","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jade","probleme_narratif":"La fiche de poste de la station est incomplète.","enjeu":"Sans fiche de poste, les apprentis se trompent de geste.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties III.2 et IV.4","competence_programme":"Dire à quoi servent le tamis vibrant et le séparateur magnétique","pourquoi_ce_savoir_ici":"Connaître son poste, c'est connaître ses machines et ses règles.","reaction_du_decor":{"effet":"eclat","description":"La fiche s'imprime et se colle au mur."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"epuration-purification","type":"trous","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Un tamis vibrant trie selon la taille ; les aimants attirent le fer ; la flottation sépare le feldspath de la silice. Contre les poussières : masque, et jamais de balayage à sec.","_brouillon":["zones"],"niveaux":["timonier"],"timonier":{"texte":"<p>Le [[tamis]] vibrant trie les grains selon leur [[taille]]. Les [[aimants]] attirent les particules de [[fer]]. Pour séparer le feldspath de la silice, on utilise la [[flottation]]. Pour se protéger des poussières, on porte un [[masque]] et on ne balaie jamais à [[sec]].</p>","etiquettes":["tamis","taille","aimants","fer","flottation","masque","sec","couleur","four"],"consigne":"Complète la fiche de poste de la station d'épuration avec les bonnes étiquettes. Deux étiquettes sont en trop.","indices":["Le premier mot est le nom de la machine qui trie.","Les aimants attirent un métal.","On travaille avec un masque ; on ne balaie jamais à sec."],"dialogue":"La fiche de poste a des trous. Deux étiquettes sont en trop."}}]},{"numero":5,"id":"le-laboratoire-des-matieres-dures-feldspath-sable-de-silice-et-chamotte","titre":"Le laboratoire des matières dures","lieu":"Le laboratoire des matières dures","matiere":"","periode_conseillee":"","episode":"Des bacs d'échantillons, deux concasseurs miniatures et un tableau des matières dures. Madame Aubry vérifie une étiquette.","scenarimage":"","mot":"CONCASSER","mot_origine":"Le mot-clé de la salle 5.","air":null,"cinematique_ouverture":"transition-e5","cinematique_fin":"fin-e5","etats_decor":[],"enigmes":[{"id":"e5-1","escale":5,"ordre":1,"titre":"Les étiquettes du laboratoire","decor":"dures","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"aubry","probleme_narratif":"Les étiquettes des échantillons sont mélangées.","enjeu":"Un échantillon mal étiqueté, et le lot de pâte est faux.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie IV","competence_programme":"Dire comment on obtient le feldspath, le sable de silice et la chamotte","pourquoi_ce_savoir_ici":"Chaque matière dure a sa description.","reaction_du_decor":{"effet":"eclat","description":"Les étiquettes retrouvent leurs échantillons."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"matieres-dures","type":"association","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Feldspath : fondant, qui aide la pâte à fondre à la cuisson. Sable de silice : dégraissant. Chamotte : argile déjà cuite, puis broyée. Concasseur à mâchoires : la roche est écrasée par pression. Concasseur à percussion : la roche éclate sous les chocs. Tessons broyés : débris de biscuits broyés puis tamisés.","_brouillon":["zones"],"matelot":{"paires":[{"g":"Feldspath","d":"Fondant : aide la pâte à fondre à la cuisson"},{"g":"Sable de silice","d":"Dégraissant : rend la pâte moins collante"},{"g":"Chamotte","d":"Argile déjà cuite, puis broyée"},{"g":"Concasseur à mâchoires","d":"La roche est écrasée par pression"}],"consigne":"Madame Aubry a mélangé les étiquettes de ses échantillons. Relie chaque matière ou machine à ce qui la décrit.","indices":["Le feldspath aide à fondre.","La chamotte a déjà connu le four.","Le concasseur à mâchoires écrase."],"dialogue":"Dernière étape : les matières dures. Le feldspath, le sable de silice, la chamotte : trois matières qui ne se modèlent pas, mais sans lesquelles la pâte ne tiendrait pas. Montrez-moi que vous savez d'où elles viennent et comment on les prépare, et le dernier tampon est à vous."},"timonier":{"paires":[{"g":"Feldspath","d":"Fondant extrait d'un gisement rocheux"},{"g":"Sable de silice","d":"Dégraissant lavé, tamisé et parfois broyé"},{"g":"Chamotte","d":"Dégraissant simple, fait d'argile déjà cuite"},{"g":"Concasseur à mâchoires","d":"La roche est écrasée par pression"},{"g":"Concasseur à percussion","d":"La roche éclate sous les chocs"},{"g":"Tessons broyés","d":"Débris de biscuits broyés puis tamisés"}],"consigne":"Relie chacune des six entrées à ce qui la décrit.","indices":["Les concasseurs travaillent sur les roches.","Percussion = chocs.","Les tessons sont des débris de biscuits."],"dialogue":"Dernière étape : les matières dures. Le feldspath, le sable de silice, la chamotte : trois matières qui ne se modèlent pas, mais sans lesquelles la pâte ne tiendrait pas. Montrez-moi que vous savez d'où elles viennent et comment on les prépare, et le dernier tampon est à vous."}},{"id":"e5-2","escale":5,"ordre":2,"titre":"Les trois échantillons","decor":"dures","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"aubry","probleme_narratif":"Trois bacs attendent leurs matières.","enjeu":"Du sable dans le bac du feldspath, et la pâte fond mal.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties IV.1, IV.2 et IV.3","competence_programme":"Dire comment on obtient le feldspath, le sable de silice et la chamotte","pourquoi_ce_savoir_ici":"Chaque matière dure a son rôle dans la pâte.","reaction_du_decor":{"effet":"ouverture","description":"Les trois bacs se remplissent de poudres de couleurs différentes."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"matieres-dures","type":"tri","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Feldspath : gisement rocheux, explosifs, gros blocs concassés puis broyés et tamisés. Sable de silice : en surface (pelleteuse) ou enfoui (on retire la couche supérieure), puis lavé, tamisé, parfois broyé. Chamotte : tessons broyés et tamisés, ou argile calcinée à une température plus haute que la cuisson de la pâte, puis broyée et tamisée.","_brouillon":["zones"],"matelot":{"colonnes":[{"id":"fel","titre":"Feldspath"},{"id":"sab","titre":"Sable de silice"},{"id":"cha","titre":"Chamotte"}],"cartes":[{"txt":"Extrait avec des explosifs","col":"fel"},{"txt":"Gros blocs de roche concassés","col":"fel"},{"txt":"Lavé pour enlever l'argile","col":"sab"},{"txt":"Extrait avec une pelleteuse","col":"sab"},{"txt":"Débris de biscuits broyés","col":"cha"},{"txt":"Argile déjà cuite, puis broyée","col":"cha"}],"consigne":"Trois bacs attendent : feldspath, sable de silice et chamotte. Range chaque étiquette dans le bon bac.","indices":["Les explosifs servent pour la roche.","Le sable se lave.","La chamotte vient d'une argile déjà cuite."],"dialogue":"Feldspath, sable de silice ou chamotte ? Rangez chaque étiquette."},"timonier":{"colonnes":[{"id":"fel","titre":"Feldspath"},{"id":"sab","titre":"Sable de silice"},{"id":"cha","titre":"Chamotte"}],"cartes":[{"txt":"Gisement rocheux, techniques minières","col":"fel"},{"txt":"Concassé, broyé puis tamisé","col":"fel"},{"txt":"Sert de fondant","col":"fel"},{"txt":"Sable de Fontainebleau, en surface","col":"sab"},{"txt":"Couche supérieure du sol retirée pour l'atteindre","col":"sab"},{"txt":"Lavé, tamisé, parfois broyé","col":"sab"},{"txt":"Tessons de biscuits broyés puis tamisés","col":"cha"},{"txt":"Argile calcinée plus fort que la cuisson de la pâte","col":"cha"},{"txt":"Dégraissant simple","col":"cha"}],"consigne":"Range les neuf étiquettes dans le bon bac : feldspath, sable de silice ou chamotte.","indices":["Les blocs de roche sont ceux du feldspath.","Fontainebleau : un sable de surface.","Calcinée = chauffée plus fort que la pâte."],"dialogue":"Neuf étiquettes, trois bacs : feldspath, sable de silice, chamotte."}},{"id":"e5-3","escale":5,"ordre":3,"titre":"Les questions de Madame Aubry","decor":"dures","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"aubry","probleme_narratif":"Madame Aubry veut s'assurer que vous connaissez vos matières.","enjeu":"Elle ne signe pas le dernier tampon à la légère.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, parties IV.2 et IV.3","competence_programme":"Dire comment on obtient le feldspath, le sable de silice et la chamotte","pourquoi_ce_savoir_ici":"Les matières dures s'obtiennent en les concassant et en les broyant.","reaction_du_decor":{"effet":"lumiere","description":"Le tampon de Madame Aubry s'illumine."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"matieres-dures","type":"qcm","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Pour atteindre un sable enfoui, on retire la couche supérieure du sol. Dans un concasseur à percussion, la roche éclate sous les chocs. La chamotte est de l'argile déjà cuite, puis broyée. Une argile calcinée est chauffée à une température plus haute que la cuisson de la pâte, puis broyée et tamisée. Après l'extraction, le sable est lavé, tamisé, et parfois broyé.","_brouillon":["zones"],"matelot":{"questions":[{"q":"Pour atteindre un sable enfoui, on…","options":["retire la couche supérieure du sol","attend la pluie","utilise un aimant"],"bonne":0,"explication":"On dégage le sable en retirant le dessus."},{"q":"Dans un concasseur à percussion, la roche…","options":["est écrasée par pression","éclate sous les chocs","fond"],"bonne":1,"explication":"Elle est projetée à grande vitesse."},{"q":"La chamotte est…","options":["de l'argile déjà cuite, puis broyée","un sable lavé","un fondant"],"bonne":0,"explication":"C'est un dégraissant simple."}],"consigne":"Madame Aubry vérifie tes connaissances. Choisis la bonne réponse à chaque question.","indices":["Il faut creuser pour atteindre le sable enfoui.","Percussion = chocs.","Chamotte = déjà cuite."],"dialogue":"Quelques questions, et je signe."},"timonier":{"questions":[{"q":"Une argile calcinée est chauffée…","options":["moins que la cuisson de la pâte","à une température plus haute que la cuisson de la pâte","à la même température que la pâte"],"bonne":1,"explication":"Elle est ensuite broyée et tamisée."},{"q":"Après son extraction, le sable de silice est…","options":["cuit puis aimanté","lavé, tamisé et parfois broyé","mélangé à de l'eau salée"],"bonne":1,"explication":"Le lavage enlève l'argile et les impuretés."},{"q":"Pourquoi les concasseurs à mâchoires écrasent-ils la roche ?","options":["Par pression","Par flottation","Par magnétisme"],"bonne":0,"explication":"Mâchoires, giratoire et cône écrasent par pression."}],"consigne":"Madame Aubry attend des réponses précises. Réponds à ses trois questions.","indices":["Calcinée = chauffée plus fort.","Les tessons sont des débris de biscuits.","Le sable passe d'abord à l'eau."],"dialogue":"Des questions précises : je n'accepte que des réponses exactes."}},{"id":"e5-4","escale":5,"ordre":4,"titre":"Du bloc à la poudre","decor":"dures","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"aubry","probleme_narratif":"Le bloc de roche doit devenir une poudre utilisable.","enjeu":"Sans ordre des étapes, la roche reste un bloc.","episode_du_roman":"Cours « Préparation des matières premières des pâtes céramiques », CAP, partie I, « Vue d'ensemble »","competence_programme":"Dire comment on obtient le feldspath, le sable de silice et la chamotte","pourquoi_ce_savoir_ici":"Du bloc à la poudre : on concasse, on broie, on tamise.","reaction_du_decor":{"effet":"ouverture","description":"Le bloc se transforme en une poudre fine."},"liberte_ou_anachronisme":"Manufacture et personnages inventés ; toutes les données techniques viennent du cours.","lecon":"matieres-dures","type":"ordre","niveau_variantes":"Essentiel (grade matelot) : repères et données réduites. Expert (grade timonier) : sans repères, plus de cartes, chiffres du cours.","correction_origine":"Roches et sables : extraire, concasser et broyer, tamiser, puis purifier si besoin (aimants ou flottation).","_brouillon":["zones"],"niveaux":["timonier"],"timonier":{"items":[{"txt":"Extraire","rang":1},{"txt":"Concasser et broyer","rang":2},{"txt":"Tamiser","rang":3},{"txt":"Purifier (si besoin)","rang":4}],"consigne":"Remets dans l'ordre les quatre étapes de préparation d'une roche (le feldspath, par exemple), de la carrière à la matière prête.","indices":["On commence par sortir la roche du gisement.","Les blocs sont d'abord concassés, puis broyés.","La purification n'est faite que si besoin."],"dialogue":"Remettez les étapes dans l'ordre, du bloc brut à la matière prête."}}]}]},"lecons":{"rayons":[{"id":"lecons","titre":"Rayon des leçons","icone":"📖"}],"lecons":[{"id":"gisement-extraction","rayon":"lecons","fiche":1,"icone":"📖","titre":"Pourquoi préparer ? Trouver et extraire l'argile","escale":1,"competence":"Expliquer pourquoi on prépare les matières premières ; Citer dans l'ordre les étapes de préparation de l'argile ; Expliquer comment on trouve et on extrait l'argile","essentiel":"<h4>Pourquoi préparer ?</h4><p>Dans la nature, les matières premières ne sont <b>pas prêtes à l'emploi</b> : elles contiennent des <b>impuretés</b>, des morceaux trop gros, trop d'eau. On les prépare pour que la pâte soit <b>stable</b> et de <b>qualité constante</b>.</p><h4>Les étapes pour l'argile</h4><p><b>Analyser le terrain</b>, <b>extraire</b>, <b>pourrissement</b>, <b>broyer</b>, <b>épurer</b>, <b>maturation</b>.</p><div class='encadre'>Avant d'extraire, on découpe le terrain en carrés (une <b>grille</b>) et on prélève <b>un échantillon par carré</b> : on trouve ainsi la <b>meilleure couche</b>.</div>","approfondi":"<h4>Pourquoi préparer ?</h4><p>Dans la nature, les matières premières ne sont <b>pas prêtes à l'emploi</b> : elles contiennent des <b>impuretés</b>, des morceaux trop gros, trop d'eau, des grains de tailles différentes. Il faut les <b>extraire</b>, les <b>casser</b>, les <b>trier</b>, les <b>nettoyer</b>, puis parfois les laisser <b>reposer</b>. Ainsi la pâte est <b>stable</b> et de <b>qualité constante</b> : la pièce se modèle, sèche et cuit toujours de la même façon.</p><h4>Trouver la bonne couche</h4><p>Un <b>gisement</b> est fait de plusieurs <b>couches</b> (les strates), toutes <b>différentes</b>. Avant d'extraire, on <b>analyse le terrain</b> : on le découpe en carrés, c'est une <b>grille</b>, et on prélève <b>un échantillon par carré</b>. On repère ainsi la <b>meilleure couche</b>.</p><h4>Extraire</h4><p>L'argile est extraite dans des <b>carrières à ciel ouvert</b>, avec des <b>excavatrices</b> et des <b>camions-bennes</b>. En général, l'extraction a lieu à <b>l'entrée de l'hiver</b>.</p><div class='encadre'>Une argile <b>« maigre »</b> (sableuse) contient beaucoup d'<b>impuretés</b> : produit de moins bonne qualité. Une argile <b>« grasse »</b> (plastique) est quasiment <b>pure</b> : produit de meilleure qualité.</div><h4>Deux filières</h4><p>Pour l'<b>argile</b> : analyser le terrain, extraire, pourrissement, broyer, épurer, maturation. Pour les <b>roches et sables</b> : extraire, concasser et broyer, tamiser, purifier si besoin.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>gisement</b></td><td>endroit où une matière (argile, roche, sable) s'est accumulée naturellement</td></tr><tr><td><b>impureté</b></td><td>matière qu'on ne veut pas dans la pâte (racines, cailloux, fer)</td></tr><tr><td><b>strates</b></td><td>couches d'un gisement, toutes différentes</td></tr><tr><td><b>argile grasse</b></td><td>argile plastique, quasiment pure</td></tr></table><h4>Les six étapes de préparation de l'argile</h4><table class='tab-lecon'><tr><td>1</td><td>analyser le terrain</td></tr><tr><td>2</td><td>extraire</td></tr><tr><td>3</td><td>pourrissement</td></tr><tr><td>4</td><td>broyer</td></tr><tr><td>5</td><td>épurer</td></tr><tr><td>6</td><td>maturation</td></tr></table>","expert":"<div class='encadre'><b>Les deux argiles</b> — Argile « maigre » (sableuse) : beaucoup d'impuretés, produit de moins bonne qualité. Argile « grasse » (plastique) : quasiment pure, produit de meilleure qualité. <i>Cours « Préparation des matières premières des pâtes céramiques », CAP, partie II.1.</i></div>","dans_le_roman":"Voir la salle 1."},{"id":"pourrissement-maturation","rayon":"lecons","fiche":2,"icone":"📖","titre":"Le pourrissement et la maturation","escale":2,"competence":"Expliquer le pourrissement de l'argile ; Expliquer la maturation et le taux d'humidité","essentiel":"<h4>Le pourrissement</h4><p>L'argile est stockée <b>dehors</b> pendant <b>3 à 24 mois</b>. Pluie, gel et dégel <b>fragmentent</b> les grains. Résultat : l'argile devient plus <b>plastique</b> et plus <b>résistante</b>.</p><h4>La maturation</h4><p>L'argile est entreposée <b>au moins 2 semaines</b> dans un <b>silo humide et sombre</b>. Son <b>taux d'humidité</b> baisse : de <b>18-22 %</b> à <b>13-18 %</b>.</p>","approfondi":"<h4>Le pourrissement : le repos dehors</h4><p>L'argile est <b>stockée dehors</b> pendant <b>3 à 24 mois</b>. Elle subit la <b>pluie</b>, le <b>gel</b> et le <b>dégel</b> : les grains se <b>fragmentent</b>. Des <b>bactéries</b> décomposent les restes de plantes. Résultat : l'argile devient plus <b>plastique</b> et plus <b>résistante</b>.</p><h4>La maturation : le repos au silo</h4><p>Après le broyage et l'épuration, l'argile est entreposée <b>au moins 2 semaines</b> dans un <b>silo humide et sombre</b>. Ses <b>propriétés</b> changent et son <b>taux d'humidité</b> (la quantité d'eau) baisse.</p><div class='encadre'>Argile <b>fraîchement extraite</b> : <b>18 %</b> à <b>22 %</b> d'eau. Après la <b>maturation</b> : <b>13 %</b> à <b>18 %</b>.</div><h4>Deux repos, deux effets</h4><p>Le pourrissement agit sur les <b>grains</b> et les <b>restes de plantes</b>, dehors, pendant des <b>mois</b>. La maturation agit sur l'<b>humidité</b>, au silo, pendant des <b>semaines</b>. Les deux rendent l'argile prête à l'emploi.</p><h4>Pourquoi laisser reposer ?</h4><p>Une matière première n'est jamais prête à l'emploi en sortant du gisement. En la laissant <b>reposer</b>, on obtient une argile plus <b>plastique</b> et plus <b>résistante</b>, donc une pâte <b>stable</b>, dont la qualité reste constante d'un lot à l'autre.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>pourrissement</b></td><td>repos de l'argile dehors, 3 à 24 mois</td></tr><tr><td><b>maturation</b></td><td>repos de l'argile au silo, au moins 2 semaines</td></tr><tr><td><b>taux d'humidité</b></td><td>quantité d'eau contenue dans l'argile</td></tr><tr><td><b>silo</b></td><td>grand réservoir où l'on entrepose la matière</td></tr></table><h4>Les deux repos de l'argile</h4><table class='tab-lecon'><tr><td>dehors</td><td>pourrissement : 3 à 24 mois, pluie, gel et dégel</td></tr><tr><td>au silo</td><td>maturation : au moins 2 semaines, humidité de 18-22 % à 13-18 %</td></tr></table>","expert":"<div class='encadre'><b>Le taux d'humidité de l'argile</b> — Argile fraîchement extraite : 18 % à 22 %. Après la maturation : 13 % à 18 %. <i>Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.3.</i></div>","dans_le_roman":"Voir la salle 2."},{"id":"broyage","rayon":"lecons","fiche":3,"icone":"📖","titre":"Le broyage de l'argile","escale":3,"competence":"Expliquer ce qu'est le broyage ; Connaître le principe des principales machines à broyer l'argile","essentiel":"<p>Le <b>broyage</b> casse l'argile en <b>petits morceaux</b> : on réduit sa taille.</p><ul><li><b>Broyeur à meule</b> : deux meules <b>écrasent</b> l'argile.</li><li><b>Brise-mottes</b> : rouleaux ou marteaux <b>cassent les mottes</b>.</li><li><b>Broyeur à marteaux</b> : des marteaux <b>frappent</b> l'argile ; elle sort par une <b>grille</b>.</li><li><b>Broyeur à billes</b> : un cylindre rempli de <b>billes</b> ; le <b>frottement</b> fragmente l'argile.</li></ul>","approfondi":"<p>Le <b>broyage</b> casse l'argile en petits morceaux : on <b>réduit sa taille</b>. Plusieurs machines sont utilisées.</p><ul><li><b>Broyeur à meule</b> : deux <b>meules</b> qui tournent <b>écrasent</b> l'argile.</li><li><b>Brise-mottes</b> : des rouleaux ou des marteaux <b>cassent les mottes</b>.</li><li><b>Désagrégateur</b> : une chemise lisse et une chemise striée avec des <b>lames</b> <b>désagrègent</b> l'argile.</li><li><b>Broyeur à marteaux</b> : des marteaux qui tournent vite <b>frappent</b> l'argile ; elle sort quand elle est assez fine, à travers une <b>grille</b>.</li><li><b>Broyeur à billes (alsing)</b> : un cylindre qui tourne, rempli de <b>billes</b> ; le <b>frottement</b> fragmente l'argile.</li></ul><div class='encadre'>Le broyage à billes se fait <b>à sec</b> ou <b>avec de l'eau</b> : <b>un tiers de billes, un tiers d'argile, un tiers d'eau</b>. Le broyeur à billes sert aussi pour les <b>roches</b>.</div><h4>Ne pas confondre</h4><p>Un broyeur <b>réduit la taille</b>. Un tamis <b>trie</b> les grains selon leur taille : il intervient à l'<b>épuration</b>, pas au broyage.</p><h4>Choisir sa machine</h4><p>Chaque machine agit autrement : la meule <b>écrase</b>, le brise-mottes <b>casse</b>, le désagrégateur <b>désagrège</b>, les marteaux <b>frappent</b>, les billes <b>frottent</b>. Après le broyage, l'argile passe à l'<b>épuration</b> pour être débarrassée de ses impuretés.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>motte</b></td><td>gros morceau d'argile compact</td></tr><tr><td><b>alsing</b></td><td>autre nom du broyeur à billes</td></tr><tr><td><b>broyer</b></td><td>réduire en petits morceaux ou en poudre</td></tr><tr><td><b>désagréger</b></td><td>défaire l'argile en séparant ses morceaux</td></tr></table><h4>Un verbe pour chaque machine</h4><table class='tab-lecon'><tr><td>écraser</td><td>broyeur à meule</td></tr><tr><td>casser</td><td>brise-mottes</td></tr><tr><td>désagréger</td><td>désagrégateur</td></tr><tr><td>frapper</td><td>broyeur à marteaux</td></tr><tr><td>frotter</td><td>broyeur à billes</td></tr></table>","expert":"<div class='encadre'><b>Le broyage à l'eau</b> — Dans un broyeur à billes, le broyage peut se faire avec de l'eau : un tiers de billes, un tiers d'argile, un tiers d'eau. <i>Cours « Préparation des matières premières des pâtes céramiques », CAP, partie III.1.</i></div>","dans_le_roman":"Voir la salle 3."},{"id":"epuration-purification","rayon":"lecons","fiche":4,"icone":"📖","titre":"L'épuration, la purification et la sécurité","escale":4,"competence":"Dire à quoi servent le tamis vibrant et le séparateur magnétique ; Expliquer la flottation ; Connaître les règles de sécurité face aux poussières","essentiel":"<h4>L'épuration de l'argile</h4><p>Le <b>tamis vibrant</b> trie les grains selon leur taille : il élimine les <b>impuretés</b> (feuilles, racines) et les grains trop gros. Le <b>déferrage</b> utilise des <b>aimants</b> qui attirent les particules de <b>fer</b>.</p><h4>La flottation</h4><p>Dans un mélange d'eau et de poudre, on ajoute des <b>réactifs</b> et de l'<b>air</b> : une matière monte en <b>mousse</b>, l'autre reste au fond.</p><div class='encadre'>Sécurité : les poussières fines sont dangereuses pour les <b>poumons</b>. <b>Masque</b>, aspiration ou humide, et <b>jamais de balayage à sec</b>.</div>","approfondi":"<h4>L'épuration de l'argile</h4><p>L'épuration enlève les <b>impuretés</b>. L'<b>épuration mécanique</b> est le <b>tamisage</b> : un <b>tamis vibrant</b> trie les grains selon leur taille et élimine les impuretés (feuilles, racines…) et les grains trop gros. L'<b>épuration magnétique</b> est le <b>déferrage</b> : des <b>aimants</b> ou <b>électro-aimants</b> attirent les particules de <b>fer</b>, qui sont séparées de l'argile (sèche ou en barbotine).</p><h4>Purifier les roches et les sables</h4><p>Comme pour l'argile, la <b>séparation magnétique</b> enlève le fer. La <b>flottation</b> sépare deux matières : on ajoute des <b>réactifs</b> et de l'<b>air</b> dans un mélange eau + poudre ; une des matières <b>s'accroche aux bulles</b> et <b>monte en mousse</b>, l'autre <b>reste au fond</b>. Exemple : séparer le <b>feldspath</b> de la <b>silice</b>.</p><div class='encadre'><b>Sécurité</b> : le broyage, le concassage et le tamisage produisent des <b>poussières fines</b> (silice, argile sèche) dangereuses pour les <b>poumons</b>. Porter un <b>masque</b>, travailler <b>avec aspiration</b> ou <b>à l'humide</b>, et ne jamais <b>balayer à sec</b>.</div><h4>Retenir</h4><p>Le <b>tamis</b> trie selon la <b>taille</b>, l'<b>aimant</b> retire le <b>fer</b>, la <b>flottation</b> sépare deux matières grâce aux <b>bulles</b>. Toutes ces opérations visent le même but : une matière <b>propre</b>, sans impureté, pour une pâte de qualité constante.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>épuration</b></td><td>action d'enlever les impuretés</td></tr><tr><td><b>barbotine</b></td><td>argile mélangée à de l'eau</td></tr><tr><td><b>déferrage</b></td><td>retrait des particules de fer avec des aimants</td></tr><tr><td><b>flottation</b></td><td>séparation de deux matières grâce à des bulles</td></tr></table><h4>Trois moyens d'épurer ou de purifier</h4><table class='tab-lecon'><tr><td>tamis vibrant</td><td>trie selon la taille, retire les impuretés</td></tr><tr><td>aimants</td><td>attirent le fer</td></tr><tr><td>flottation</td><td>une matière monte en mousse, l'autre reste au fond</td></tr></table>","expert":"<div class='encadre'><b>Le panneau de sécurité</b> — Poussières fines (silice, argile sèche) : danger pour les poumons. Porter un masque. Travailler avec aspiration ou à l'humide. Ne jamais balayer à sec. <i>Cours « Préparation des matières premières des pâtes céramiques », CAP, encadré « Sécurité ».</i></div>","dans_le_roman":"Voir la salle 4."},{"id":"matieres-dures","rayon":"lecons","fiche":5,"icone":"📖","titre":"Les matières dures : feldspath, sable de silice, chamotte","escale":5,"competence":"Dire comment on obtient le feldspath, le sable de silice et la chamotte ; Distinguer les deux types de concasseurs ; Distinguer fondant et dégraissant","essentiel":"<ul><li><b>Feldspath</b> (<b>fondant</b>) : dans un gisement rocheux, extrait avec des <b>explosifs</b> ; les blocs sont <b>concassés</b>, <b>broyés</b>, <b>tamisés</b>.</li><li><b>Sable de silice</b> (<b>dégraissant</b>) : extrait <b>en surface</b> à la pelleteuse, ou <b>enfoui</b> ; puis <b>lavé</b>, <b>tamisé</b>.</li><li><b>Chamotte</b> (<b>dégraissant</b>) : <b>argile déjà cuite</b>, <b>broyée</b> et tamisée.</li></ul><div class='encadre'>Concasseur à <b>mâchoires</b> : la roche est <b>écrasée</b>. Concasseur à <b>percussion</b> : la roche <b>éclate sous les chocs</b>.</div>","approfondi":"<h4>Le feldspath (fondant)</h4><p>Le feldspath, la pegmatite et la néphéline sont dans des <b>gisements rocheux</b>. On les extrait avec des <b>techniques minières</b>, souvent des <b>explosifs</b>, pour obtenir de gros <b>blocs de roche</b>. Ils sont <b>concassés</b> (réduits en morceaux de quelques centimètres ou millimètres), puis <b>broyés</b> et <b>tamisés</b>.</p><p>Concasseurs <b>à mâchoires, giratoire, à cône</b> : la roche est <b>écrasée par pression</b>. Concasseur <b>à percussion</b> : la roche est projetée à grande vitesse et <b>éclate sous les chocs</b>.</p><h4>Le sable de silice (dégraissant)</h4><p>Le sable est <b>en surface</b> (par exemple le sable de Fontainebleau) : on l'extrait directement avec une <b>pelleteuse</b>. S'il est <b>enfoui</b>, on <b>retire la couche supérieure</b> du sol. Ensuite, il est <b>lavé</b> (pour enlever l'argile et les impuretés), <b>tamisé</b>, et parfois <b>broyé</b>.</p><h4>La chamotte (dégraissant)</h4><p>Les <b>tessons broyés</b> : des débris de <b>biscuits</b> (pièces déjà cuites) sont broyés puis tamisés. Les <b>argiles calcinées</b> : de l'argile est <b>calcinée</b> à une température <b>plus haute</b> que la cuisson de la pâte, puis broyée et tamisée.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>chamotte</b></td><td>argile déjà cuite, puis broyée</td></tr><tr><td><b>fondant</b></td><td>matière qui aide la pâte à fondre à la cuisson</td></tr><tr><td><b>concasser</b></td><td>casser une roche en morceaux de quelques centimètres ou millimètres</td></tr><tr><td><b>calciner</b></td><td>chauffer très fort une argile</td></tr></table><h4>Trois matières dures, trois préparations</h4><table class='tab-lecon'><tr><td>feldspath</td><td>gisement rocheux, explosifs, concassage, broyage, tamisage</td></tr><tr><td>sable de silice</td><td>surface ou enfoui, lavage, tamisage, parfois broyage</td></tr><tr><td>chamotte</td><td>tessons ou argile calcinée, broyage, tamisage</td></tr></table>","expert":"<div class='encadre'><b>Les deux types de chamotte</b> — Tessons broyés : des débris de biscuits sont broyés puis tamisés. Argiles calcinées : de l'argile est calcinée à une température plus haute que la cuisson de la pâte, puis broyée et tamisée. <i>Cours « Préparation des matières premières des pâtes céramiques », CAP, partie IV.3.</i></div>","dans_le_roman":"Voir la salle 5."}]},"decors-fx":{"decors":{"carriere":{"titre":"La carrière d'argile, à ciel ouvert","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le panneau des mots","x":7,"y":44,"w":18,"h":24,"description":"Un panneau de chantier : six mots du métier, six définitions effacées."},{"id":"objet-2","libelle":"Les gradins","x":28,"y":62,"w":24,"h":28,"description":"Les gradins de la carrière, où les panneaux de la filière ont été mélangés par le vent."},{"id":"objet-3","libelle":"L'engin d'Odile","x":58,"y":58,"w":14,"h":28,"description":"L'engin de la cheffe de carrière, avec son carnet posé sur le capot."},{"id":"objet-4","libelle":"La fiche d'analyse","x":80,"y":58,"w":16,"h":30,"description":"La fiche d'analyse du terrain, à moitié effacée."}],"etats":{"normal":{"filtre":"none"}},"_brouillon":"zones à caler sur l'image (outils/caler-effets.html)"},"parc":{"titre":"Le parc d'argile et le silo, derrière la carrière","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le tas sous la pluie","x":4,"y":60,"w":52,"h":30,"description":"L'argile fraîchement sortie, qui pourrit dehors sous la pluie."},{"id":"objet-2","libelle":"Le silo","x":72,"y":42,"w":15,"h":16,"description":"Le silo humide et sombre où l'argile mûrit."},{"id":"objet-3","libelle":"L'afficheur du parc","x":11,"y":41,"w":24,"h":13,"description":"L'afficheur du parc : durées de repos et taux d'humidité."},{"id":"objet-4","libelle":"Le cadran du silo","x":75,"y":60,"w":11,"h":12,"description":"Le cadran à trois molettes qui verrouille la porte du silo."}],"etats":{"normal":{"filtre":"none"}},"_brouillon":"zones à caler sur l'image (outils/caler-effets.html)"},"broyage":{"titre":"L'atelier de broyage","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le panneau des plaques","x":86,"y":41,"w":12,"h":15,"description":"Le panneau « Plaques manquantes » : les plaques des machines sont tombées."},{"id":"objet-2","libelle":"Le plan de l'atelier","x":30,"y":6,"w":22,"h":24,"description":"Le plan de l'atelier : des postes numérotés, sans nom de machine."},{"id":"objet-3","libelle":"Le poste de Karim","x":59,"y":46,"w":14,"h":36,"description":"La grosse machine du technicien : Karim vérifie vos connaissances ici."},{"id":"objet-4","libelle":"Les machines en marche","x":29,"y":52,"w":23,"h":20,"description":"Une machine qui tourne, mais qui ne broie pas."}],"etats":{"normal":{"filtre":"none"}},"_brouillon":"zones à caler sur l'image (outils/caler-effets.html)"},"epuration":{"titre":"La station d'épuration","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le tamis vibrant","x":6,"y":48,"w":23,"h":40,"description":"Un tamis vibrant : il trie les grains selon leur taille."},{"id":"objet-2","libelle":"La cellule de flottation","x":56,"y":45,"w":28,"h":44,"description":"La cellule où deux poudres se séparent."},{"id":"objet-3","libelle":"Le panneau de sécurité","x":87,"y":41,"w":11,"h":34,"description":"Le panneau des règles de sécurité de la station."},{"id":"objet-4","libelle":"La fiche de poste","x":38,"y":56,"w":15,"h":30,"description":"La fiche de poste, affichée près de l'aimant."}],"etats":{"normal":{"filtre":"none"}},"_brouillon":"zones à caler sur l'image (outils/caler-effets.html)"},"dures":{"titre":"Le laboratoire des matières dures","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le tableau des étiquettes","x":7,"y":38,"w":41,"h":23,"description":"Le tableau du laboratoire : une matière, un rôle, des étiquettes mélangées."},{"id":"objet-2","libelle":"Les trois bacs","x":7,"y":66,"w":48,"h":22,"description":"Trois bacs : feldspath, sable de silice, chamotte."},{"id":"objet-3","libelle":"Le bureau de Madame Aubry","x":77,"y":54,"w":12,"h":32,"description":"La machine de la responsable du laboratoire."},{"id":"objet-4","libelle":"Le concasseur","x":62,"y":54,"w":12,"h":32,"description":"Le concasseur : un bloc de roche y devient poudre."}],"etats":{"normal":{"filtre":"none"}},"_brouillon":"zones à caler sur l'image (outils/caler-effets.html)"}}},"dialogues":{"_commentaire":"Brouillon généré par le migrateur : reformuler dans le ton de chaque personnage.","accueil":{"personnage":"maelle","texte":"Bonjour, je suis Maëlle, apprentie en deuxième année. Bienvenue à la manufacture des Trois Fours ! Demain matin, un nouveau lot de pâte doit être lancé. Problème : le bon de lancement n'est pas signé. Pour qu'il le soit, chacune des cinq étapes de la préparation des matières premières doit être validée par son responsable, qui appose son tampon et vous donne un mot. Les cinq mots ouvriront le bon de lancement. On commence par la carrière ?"},"coffre":{"personnage":"maelle","texte":"Le coffre ne s'ouvre qu'avec les mots de chaque salle, dans l'ordre. Vous les avez notés, j'espère."},"cinematiques":{"transition-e1":{"titre":"Salle 1 — La carrière","plans":[{"decor":"carriere","etat":"normal","duree":8,"personnage":"odile","texte":"Bienvenue à la carrière. Maëlle m'a prévenue : sans le bon de lancement signé, le lot de pâte de demain ne peut pas partir. Je tamponne la première étape : l'extraction. Avant de vous donner mon tampon, je veux être sûre que vous savez pourquoi on prépare les matières, et comment on trouve la bonne argile.","mouvement":"zoom"}]},"fin-e1":{"titre":"Fin de la salle 1","plans":[{"decor":"carriere","etat":"normal","duree":7,"personnage":"odile","texte":"Bien analysé ! Mon tampon porte le mot ANALYSER : on ne creuse jamais au hasard. Malik vous attend au parc d'argile.","mouvement":"glisse"}]},"transition-e2":{"titre":"Salle 2 — Le parc d'argile et le silo","plans":[{"decor":"parc","etat":"normal","duree":8,"personnage":"malik","texte":"Ici, on laisse faire le temps. L'argile qui sort de la carrière n'est pas prête : elle passe d'abord dehors, puis dans mon silo. Montrez-moi que vous savez ce qui se passe sous la pluie, et combien de temps ça prend : le tampon de l'étape deux est à ce prix.","mouvement":"zoom"}]},"fin-e2":{"titre":"Fin de la salle 2","plans":[{"decor":"parc","etat":"normal","duree":7,"personnage":"malik","texte":"Vous avez compris que le temps travaille pour nous. Mon tampon porte le mot REPOSER : l'argile a besoin de repos. Karim vous attend à l'atelier de broyage.","mouvement":"glisse"}]},"transition-e3":{"titre":"Salle 3 — L'atelier de broyage","plans":[{"decor":"broyage","etat":"normal","duree":8,"personnage":"karim","texte":"Ça grince, ça gronde, ça casse : c'est l'atelier de broyage. Pas de panique, mais tous les postes ont perdu leur plaque ce matin, et je ne sais plus quelle machine fait quoi. Aidez-moi à tout remettre en place : le tampon de l'étape trois est pour vous.","mouvement":"zoom"}]},"fin-e3":{"titre":"Fin de la salle 3","plans":[{"decor":"broyage","etat":"normal","duree":7,"personnage":"karim","texte":"L'atelier est remis en ordre, merci ! Mon tampon porte le mot BROYER . Jade vous attend à la station d'épuration.","mouvement":"glisse"}]},"transition-e4":{"titre":"Salle 4 — La station d'épuration","plans":[{"decor":"epuration","etat":"normal","duree":8,"personnage":"jade","texte":"On passe à la propreté : ici, on enlève ce qui n'a rien à faire dans une pâte. Tamis, aimants, flottation : chaque machine a son rôle. Et ici, la sécurité n'est pas une option : la poussière, ça ne pardonne pas. Prouvez-moi que vous la connaissez, et le tampon est à vous.","mouvement":"zoom"}]},"fin-e4":{"titre":"Fin de la salle 4","plans":[{"decor":"epuration","etat":"normal","duree":7,"personnage":"jade","texte":"Station propre, équipe protégée : parfait. Mon tampon porte le mot ÉPURER . Il reste le laboratoire des matières dures : Madame Aubry vous attend.","mouvement":"glisse"}]},"transition-e5":{"titre":"Salle 5 — Le laboratoire des matières dures","plans":[{"decor":"dures","etat":"normal","duree":8,"personnage":"aubry","texte":"Dernière étape : les matières dures. Le feldspath, le sable de silice, la chamotte : trois matières qui ne se modèlent pas, mais sans lesquelles la pâte ne tiendrait pas. Montrez-moi que vous savez d'où elles viennent et comment on les prépare, et le dernier tampon est à vous.","mouvement":"zoom"}]},"fin-e5":{"titre":"Fin de la salle 5","plans":[{"decor":"dures","etat":"normal","duree":7,"personnage":"maelle","texte":"Madame Aubry vous a donné le dernier mot : CONCASSER . Vous avez les cinq tampons ! Écrivez les cinq mots dans le bon de lancement, dans l'ordre des salles : le lot de pâte pourra partir demain matin.","mouvement":"glisse"}]},"fin":{"titre":"Fin de « Le bon de lancement »","plans":[{"decor":"dures","etat":"normal","duree":7,"personnage":"aubry","texte":"Le coffre est ouvert : toutes les pages sont rassemblées. Bravo, équipe !","mouvement":"zoom"}]}},"fin_escale":{"1":{"personnage":"odile","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"2":{"personnage":"malik","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"3":{"personnage":"karim","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"4":{"personnage":"jade","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"5":{"personnage":"aubry","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."}}},"personnages":{"personnages":{"maelle":{"nom":"Maëlle","court":"Maëlle","voix":{"rate":0.95,"pitch":1.0},"ton":"à préciser","fiche":"Apprentie en 2e année de CAP Décoration sur céramique, elle guide l'équipe","portrait":{}},"odile":{"nom":"Odile","court":"Odile","voix":{"rate":1.0,"pitch":1.15},"ton":"à préciser","fiche":"Cheffe de la carrière","portrait":{}},"malik":{"nom":"Malik","court":"Malik","voix":{"rate":0.9,"pitch":0.9},"ton":"à préciser","fiche":"Responsable du parc d'argile et des silos","portrait":{}},"karim":{"nom":"Karim","court":"Karim","voix":{"rate":1.05,"pitch":1.2},"ton":"à préciser","fiche":"Technicien de l'atelier de broyage","portrait":{}},"jade":{"nom":"Jade","court":"Jade","voix":{"rate":0.92,"pitch":1.05},"ton":"à préciser","fiche":"Technicienne de la station d'épuration","portrait":{}},"aubry":{"nom":"Madame Aubry","court":"Madame","voix":{"rate":1.0,"pitch":0.85},"ton":"à préciser","fiche":"Cheffe du laboratoire des matières dures","portrait":{}}}}};
